def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = {v for row in grid for v in row}
    bg = max(vals, key=lambda v: sum(row.count(v) for row in grid))
    # Enclosed area is filled with 2 only when the frame color is 8; otherwise 7.
    frame_colors = {v for v in vals if v != bg}
    fill = 2 if 8 in frame_colors else 7
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(len(grid[r])):
            if grid[r][c] != bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]; edge=False
            while q:
                y,x=q.popleft(); cells.append((y,x))
                edge |= y==0 or y==h-1 or x==0 or x==len(grid[y])-1
                for dy,dx in ((0,1),(0,-1),(1,0),(-1,0)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<len(grid[yy]) and grid[yy][xx]==bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            if not edge:
                for y,x in cells: out[y][x]=fill
    return out

